source='''def transform(grid):
    height, width = len(grid), len(grid[0])
    output = [[0] * width for _ in range(height)]
    barrier_rows = [r for r, row in enumerate(grid) if all(value == 2 for value in row)]
    barrier = barrier_rows[0] if barrier_rows else None

    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 2:
                output[r][c] = 2
            elif value == 4:
                landing = min(r + 1, height - 1)
                if barrier is not None and landing == barrier:
                    landing = r
                output[landing][c] = 4
                if barrier is not None and landing == barrier - 1:
                    distance = 1
                    while landing - distance >= 0:
                        for target_c in (c - distance, c + distance):
                            if 0 <= target_c < width:
                                output[landing - distance][target_c] = 4
                        distance += 1

    return output
'''
